const mCPUpsertPresence = `-- name: MCPUpsertPresence :exec
INSERT INTO "McpActiveSession" (id, "userId", "clientName", "clientVer", "ipAddress", "lastSeenAt", status)
VALUES (gen_random_uuid()::text, $1::text, $2::text, NULLIF($3::text, ''), NULLIF($4::text, ''), now(), 'ACTIVE')
ON CONFLICT ("userId", "clientName") DO UPDATE
SET "lastSeenAt" = now(), status = 'ACTIVE',
    "clientVer" = COALESCE(NULLIF($3::text, ''), "McpActiveSession"."clientVer"),
    "ipAddress" = COALESCE(NULLIF($4::text, ''), "McpActiveSession"."ipAddress")
`

type MCPUpsertPresenceParams struct {
	UserId     string `db:"userId" json:"userId"`
	ClientName string `db:"clientName" json:"clientName"`
	ClientVer  string `db:"clientVer" json:"clientVer"`
	IpAddress  string `db:"ipAddress" json:"ipAddress"`
}

func (q *Queries) MCPUpsertPresence(ctx context.Context, arg MCPUpsertPresenceParams) error {
	_, err := q.db.Exec(ctx, mCPUpsertPresence,
		arg.UserId,
		arg.ClientName,
		arg.ClientVer,
		arg.IpAddress,
	)
	return err
}
